$page_title='ความเป็นส่วนตัวและข้อมูลของฉัน';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/config/database.php';$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!isLoggedIn()){header('Location: '.BASE_URL.'login.php');exit;}requireCsrf(false);try{$action=$_POST['action']??'';$uid=(int)$_SESSION['user_id'];if($action==='export'){$data=[];$queries=['account'=>'SELECT id,username,full_name,email,phone,role,created_at FROM users WHERE id=?','addresses'=>'SELECT label,recipient_name,phone,address_line,subdistrict,district,province,postal_code,is_default,created_at FROM user_addresses WHERE user_id=?','orders'=>'SELECT order_no,total_amount,discount_amount,shipping_amount,payment_method,payment_status,order_status,created_at FROM orders WHERE user_id=?','reviews'=>'SELECT product_id,rating,comment,created_at FROM product_reviews WHERE user_id=?','support_tickets'=>'SELECT ticket_no,category,subject,status,created_at,updated_at FROM support_tickets WHERE user_id=?'];foreach($queries as $key=>$sql){$s=$db->prepare($sql);$s->execute([$uid]);$data[$key]=$s->fetchAll();}$data['exported_at']=date(DATE_ATOM);auditLog($db,'privacy.data.export','user',$uid);header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="kitchenmart-data-'.date('Ymd-His').'.json"');echo json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}if($action==='delete_request'){$existing=$db->prepare("SELECT id FROM support_tickets WHERE user_id=? AND category='privacy' AND status NOT IN ('resolved','closed') LIMIT 1");$existing->execute([$uid]);if($existing->fetchColumn())throw new RuntimeException('มีคำขอลบบัญชีที่กำลังดำเนินการอยู่แล้ว');$ticketNo='KM'.date('ymd').strtoupper(bin2hex(random_bytes(3)));$db->beginTransaction();$db->prepare("INSERT INTO support_tickets(ticket_no,user_id,category,subject,priority,status) VALUES(?,?,'privacy','คำขอลบบัญชีและข้อมูล','high','waiting_staff')")->execute([$ticketNo,$uid]);$ticketId=(int)$db->lastInsertId();$db->prepare('INSERT INTO support_messages(ticket_id,sender_user_id,message,is_staff) VALUES(?,?,?,0)')->execute([$ticketId,$uid,'ขอตรวจสอบและลบบัญชีตามสิทธิ์ของเจ้าของข้อมูล ทีมงานโปรดตรวจสอบคำสั่งซื้อ ภาระผูกพัน และยืนยันตัวตนก่อนดำเนินการ']);createRoleNotification($db,'admin','support','คำขอลบบัญชี '.$ticketNo,'โปรดตรวจสอบตัวตนและข้อผูกพันก่อนลบ',BASE_URL.'admin/support.php?id='.$ticketId);$db->commit();$message='รับคำขอแล้ว ทีมงานจะตรวจสอบตัวตนและรายการที่ยังดำเนินการก่อนลบ';}}catch(Throwable $e){if($db&&$db->inTransaction())$db->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'ไม่สามารถดำเนินการได้';}}
